function parseUtcInput(value){if(!value)return NaN;let m=value.match(/^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d)$/);return m?Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+m[5]):NaN}function csvCell(v){return'"'+String(v??'').replace(/"/g,'""')+'"'}function exportEventsCsv(){let rows=[['timestamp_utc','original_timestamp','source','host','event','severity','username','source_ip','original_record'],...events.map(e=>[new Date(e.epoch).toISOString(),e.originalTimestamp,e.source,e.host,e.message,e.severity,e.user,e.sourceIP,e.original])];downloadBlob(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'incident-events-'+caseId+'.csv');toast('CSV timeline downloaded')}async function apiFetch(url,options={}){let res=await fetch(url,options);if(!res.ok){let msg=await res.text();throw Error(msg.slice(0,400)||`API returned ${res.status}`)}return res}
function setDbStatus(message,state){$('dbStatus').textContent=message;$('backendBanner').dataset.state=state||'offline'}async function checkBackend(){try{let r=await apiFetch('/api/status'),d=await r.json();backendAvailable=true;setDbStatus(`SQLite connected · ${d.counts.evidence} evidence · ${d.counts.events} events`,'online');return true}catch{backendAvailable=false;setDbStatus('API unavailable · browser-only mode','offline');return false}}
async function refreshBackendRecords(){if(!backendAvailable)return;let [evRes,gapRes,anomalyRes,timeRes]=await Promise.all([apiFetch('/api/evidence'),apiFetch('/api/gaps'),apiFetch('/api/anomalies'),apiFetch('/api/time-analysis')]);let evidence=await evRes.json(),gapData=await gapRes.json(),anomalies=await anomalyRes.json(),timeRows=await timeRes.json(),all=[];for(let skip=0;skip<25000;skip+=1000){let r=await apiFetch(`/api/events?skip=${skip}&limit=1000`),chunk=await r.json();all.push(...chunk);if(chunk.length<1000)break}files=evidence.map(f=>({id:f.id,name:f.filename,text:'',bytes:null,hash:f.sha256,format:f.format,detectedFormat:f.format,tz:f.source_timezone,offset:f.clock_offset_minutes,uploadedAt:f.uploaded_at,mimeType:f.mime_type,processingStatus:f.processing_status,duplicateOfId:f.duplicate_of_id,integrityStatus:f.integrity_status,recordCount:f.record_count,fileSizeBytes:f.file_size_bytes,synthetic:f.synthetic,scenarioId:f.scenario_id}));events=all.map(e=>({id:String(e.id),evidenceId:e.evidence_id,epoch:e.timestamp_utc?Date.parse(e.timestamp_utc):NaN,originalTimestamp:e.original_timestamp,host:e.host,message:e.description,format:e.event_type,source:files.find(f=>f.id===e.evidence_id)?.name||e.evidence_id,synthetic:!!files.find(f=>f.id===e.evidence_id)?.synthetic,original:e.original_record||'',severity:e.severity,offset:e.clock_offset_minutes,user:e.username||'',sourceIP:e.source_ip||''}));gaps=gapData.map(g=>({source:g.filename,line:g.line_number,raw:g.original_text,reason:g.reason,evidenceId:g.evidence_id,synthetic:!!g.synthetic}));events.sort((a,b)=>(Number.isFinite(a.epoch)?a.epoch:Infinity)-(Number.isFinite(b.epoch)?b.epoch:Infinity));render();let status=await(await apiFetch('/api/status')).json();setDbStatus(`SQLite connected · ${status.counts.evidence} evidence · ${status.counts.events} events`,'online');$('dbEvidenceCount').textContent=status.counts.evidence;$('dbEventCount').textContent=status.counts.events;$('dbGapCount').textContent=status.counts.gaps;$('dbInvestigationCount').textContent=status.counts.investigations;$('anomalyList').innerHTML=anomalies.length?anomalies.map(a=>`<div class="gapitem"><b>${escapeHtml(a.title)}</b> · ${escapeHtml(a.confidence)}<br>${escapeHtml(a.description)}</div>`).join(''):'<div class="empty">No rule-based findings recorded.</div>';$('timeAnalysisTable').innerHTML=timeRows.length?`<table><thead><tr><th>Source</th><th>Timezone</th><th>Correction</th><th>Events</th><th>First UTC</th><th>Last UTC</th></tr></thead><tbody>${timeRows.map(t=>`<tr><td>${escapeHtml(t.filename)}${t.synthetic?' · SYNTHETIC':''}</td><td>${escapeHtml(t.source_timezone)}</td><td>${t.clock_offset_minutes} min</td><td>${t.event_count}</td><td>${escapeHtml(t.first_utc||'')}</td><td>${escapeHtml(t.last_utc||'')}</td></tr>`).join('')}</tbody></table>`:'No event timestamps stored yet.'}
async function uploadEvidenceToApi(f,format,tz,offset){let bytes=f.bytes||new TextEncoder().encode(f.text||''),fd=new FormData();fd.append('file',new Blob([bytes],{type:f.mimeType||'text/plain'}),f.name);fd.append('format',format);fd.append('source_timezone',tz);fd.append('clock_offset_minutes',String(offset));let r=await apiFetch('/api/evidence',{method:'POST',body:fd}),d=await r.json();return d.evidence}
async function refreshInvestigations(){if(!backendAvailable)return;try{let list=await(await apiFetch('/api/investigations')).json();$('investigationList').innerHTML=list.length?list.map(x=>`<div class="sourceitem"><strong>${escapeHtml(x.name)} · ${escapeHtml(x.status)}</strong><span>${escapeHtml(x.description||'No description')} · ${escapeHtml(x.created_at)}</span><br><button type="button" data-investigation="${escapeHtml(x.id)}">Open investigation</button></div>`).join(''):'<div class="empty">No saved investigations yet.</div>';document.querySelectorAll('[data-investigation]').forEach(b=>b.onclick=async()=>{let d=await(await apiFetch(`/api/investigations/${b.dataset.investigation}`)).json();activeInvestigationId=d.id;$('investigationName').value=d.name;$('investigationDescription').value=d.description;$('investigationNotes').value=d.notes;$('investigationStatus').value=d.status;applyTriage({answers:d.triage_answers||[],manual:d.manual_baseline_minutes??'',tool:d.tool_assisted_minutes??''});$('activeInvestigation').textContent=`Active investigation: ${d.name} · ${d.event_ids.length} associated events · ${d.evidence_ids.length} evidence files`});if(activeInvestigationId&&!list.some(x=>x.id===activeInvestigationId))activeInvestigationId=null;if(!activeInvestigationId&&list.length)activeInvestigationId=list[0].id;if(activeInvestigationId){let x=list.find(z=>z.id===activeInvestigationId);if(x)$('activeInvestigation').textContent=`Active investigation: ${x.name} · ${x.status}`}$('dbInvestigationCount').textContent=list.length}catch(e){toast('Could not load saved investigations')}}
async function saveInvestigationChanges(){if(!activeInvestigationId){toast('Open or create an investigation first');return}let payload={name:$('investigationName').value.trim(),description:$('investigationDescription').value,notes:$('investigationNotes').value,status:$('investigationStatus').value,triage_answers:readTriage().answers,manual_baseline_minutes:$('manualBaseline').value===''?null:Number($('manualBaseline').value),tool_assisted_minutes:$('toolTime').value===''?null:Number($('toolTime').value)};await apiFetch(`/api/investigations/${activeInvestigationId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await refreshInvestigations();toast('Investigation notes and triage comparison saved')}
async function associateEvidenceIds(ids){let unique=[...new Set(ids.filter(Boolean))];if(!activeInvestigationId||!unique.length)return;await apiFetch(`/api/investigations/${activeInvestigationId}/evidence`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:unique})})}
async function associateCurrentRecords(){if(!backendAvailable)return;let list=await(await apiFetch('/api/investigations')).json();if(!activeInvestigationId&&list.length)activeInvestigationId=list[0].id;if(!activeInvestigationId){toast('Create or open an investigation first');return}await associateEvidenceIds(files.map(f=>f.id));let ids=events.map(e=>Number(e.id)).filter(Number.isFinite);for(let i=0;i<ids.length;i+=400){let batch=ids.slice(i,i+400);await apiFetch(`/api/investigations/${activeInvestigationId}/events`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:batch})})}await refreshInvestigations();toast('Current evidence and events associated with the investigation')}
async function createInvestigationFromForm(){let name=$('investigationName').value.trim();if(!name){toast('Enter an investigation name');$('investigationName').focus();return}let r=await apiFetch('/api/investigations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,description:$('investigationDescription').value,notes:$('investigationNotes').value,triage_answers:readTriage().answers,manual_baseline_minutes:$('manualBaseline').value===''?null:Number($('manualBaseline').value),tool_assisted_minutes:$('toolTime').value===''?null:Number($('toolTime').value)})}),d=await r.json();activeInvestigationId=d.id;if($('investigationStatus').value!=='open')await apiFetch(`/api/investigations/${d.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:$('investigationStatus').value})});await associateCurrentRecords();await refreshBackendRecords();await refreshInvestigations();toast('Investigation created and saved in SQLite')}
async function loadBackendScenario(localId){let scenarioId=({s1:'ssh-bruteforce',s2:'web-application',s3:'network-activity'})[localId];if(!scenarioId){loadScenario(localId);return}try{let seed=Number($('generatorSeed').value)||13013,r=await apiFetch(`/api/scenarios/${scenarioId}/import?seed=${seed}`,{method:'POST'}),result=await r.json();caseId=localId;currentCaseName=result.scenario.name;$('caseName').textContent=`SYNTHETIC · ${result.scenario.name}`;$('caseDesc').textContent=`Generated with seed ${result.scenario.seed}; records are synthetic.`;$('crumbName').textContent=result.scenario.name;$('scenarioSelect').value=localId;applyTriage();await refreshBackendRecords();let inv=await(await apiFetch('/api/investigations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:`${result.scenario.name} · seed ${seed}`,description:'SYNTHETIC scenario generated by Tracepoint. Rule findings are not confirmed incidents.'})})).json();activeInvestigationId=inv.id;await associateCurrentRecords();await refreshInvestigations();toast('Synthetic scenario generated and imported into SQLite')}catch(e){toast('Scenario import failed: '+e.message.slice(0,120))}}
function apiReportMarkup(d){let i=d.investigation,evidence=(d.evidence||[]).map(x=>`<tr><td>${x.synthetic?'SYNTHETIC':'Uploaded'}</td><td>${escapeHtml(x.filename)}</td><td>${escapeHtml(x.id||x.evidenceId)}</td><td>${escapeHtml(x.sha256)}</td><td>${x.file_size_bytes??x.fileSizeBytes??''}</td></tr>`).join(''),rows=(d.events||[]).map(x=>`<tr><td>${escapeHtml(x.timestamp_utc||'Unnormalized')}</td><td>${escapeHtml(x.original_timestamp||'')}</td><td>${escapeHtml(x.source_ip||'')}</td><td>${escapeHtml(x.username||'')}</td><td>${escapeHtml(x.severity)}</td><td>${escapeHtml(x.description)}<small>${escapeHtml(x.original_record||'')}</small></td></tr>`).join(''),g=d.gaps||[],a=d.anomalies||[];return `<h1>Investigation report</h1><p><b>${escapeHtml(i.name)}</b> · ${escapeHtml(i.status)} · generated ${escapeHtml(d.generated_at||new Date().toISOString())}</p><p>${escapeHtml(i.description||'')}</p><h2>Evidence manifest</h2><table><thead><tr><th>Origin</th><th>Filename</th><th>Evidence ID</th><th>SHA-256</th><th>Bytes</th></tr></thead><tbody>${evidence||'<tr><td colspan="5">No evidence associated</td></tr>'}</tbody></table><h2>Normalized timeline</h2><table><thead><tr><th>UTC</th><th>Original timestamp</th><th>IP</th><th>User</th><th>Severity</th><th>Event and original record</th></tr></thead><tbody>${rows||'<tr><td colspan="6">No events associated</td></tr>'}</tbody></table><h2>Parsing gaps</h2>${g.map(x=>`<p>${escapeHtml(x.filename)}:${x.line_number} · ${escapeHtml(x.reason)}<br><code>${escapeHtml(x.original_text)}</code></p>`).join('')||'<p>No parsing gaps</p>'}<h2>Rule-based findings</h2>${a.map(x=>`<p><b>${escapeHtml(x.title)}</b> (${escapeHtml(x.confidence)}) · ${escapeHtml(x.description)}</p>`).join('')||'<p>No findings</p>'}<h2>Investigation notes</h2><p>${escapeHtml(i.notes||'No notes recorded')}</p><h2>Triage-time comparison</h2><p>Manual baseline: ${escapeHtml(d.triage?.manual_baseline_minutes??'Not recorded')} minutes · Tracepoint-assisted: ${escapeHtml(d.triage?.tool_assisted_minutes??'Not recorded')} minutes</p><p>Time saved: ${escapeHtml(d.triage?.time_saved_minutes??'Not recorded')} minutes · Improvement: ${escapeHtml(d.triage?.percentage_improvement??'Not recorded')}%</p><p>${(d.triage?.answers||[]).map((x,n)=>`${n+1}. ${escapeHtml(x)}`).join('<br>')||'No triage notes recorded'}</p><h2>Limitations</h2>${(d.limitations||[]).map(x=>`<p>${escapeHtml(x)}</p>`).join('')}`}
async function downloadApiReport(format){if(!activeInvestigationId){toast('Create or open an investigation to export its saved report');return}let r=await apiFetch(`/api/investigations/${activeInvestigationId}/report?format=${format}`),blob=await r.blob();downloadBlob(blob,`tracepoint-investigation-${activeInvestigationId}.${format==='csv'?'csv':'json'}`)}
async function generatePreview(){let id=$('generatorScenario').value,seed=Number($('generatorSeed').value)||13013;try{let d=await(await apiFetch(`/api/scenarios/${id}/generate?seed=${seed}`,{method:'POST'})).json();$('scenarioMeta').textContent=`${d.label} · ${d.name} · seed ${d.seed} · ${d.files.length} files · ${d.metadata.source_ip} · user ${d.metadata.username} · timezone variation and clock skew included`;$('scenarioFiles').innerHTML=d.files.map((f,i)=>`<div class="scenario-file"><b>${escapeHtml(f.filename)}</b> · ${escapeHtml(f.format)} · ${escapeHtml(f.source_timezone)} · correction ${f.clock_offset_minutes} min · ${new TextEncoder().encode(f.text).byteLength.toLocaleString()} bytes<button type="button" data-file-preview="${i}">Preview</button><button type="button" data-file-download="${i}">Download</button><pre id="preview-${i}" style="display:none">${escapeHtml(f.text)}</pre></div>`).join('');document.querySelectorAll('[data-file-preview]').forEach(b=>b.onclick=()=>{let p=$('preview-'+b.dataset.filePreview);p.style.display=p.style.display==='none'?'block':'none'});document.querySelectorAll('[data-file-download]').forEach(b=>b.onclick=()=>downloadGeneratedFile(Number(b.dataset.fileDownload)));window.tracepointGeneratedScenario=d;toast('Synthetic scenario generated')}catch(e){toast('Generator API failed: '+e.message.slice(0,120))}}
function downloadGeneratedFile(index){let f=window.tracepointGeneratedScenario?.files?.[index];if(!f)return;downloadBlob(new Blob([f.text],{type:'text/plain;charset=utf-8'}),f.filename)}async function downloadScenarioZip(){let id=$('generatorScenario').value,seed=Number($('generatorSeed').value)||13013,r=await apiFetch(`/api/scenarios/${id}/download?seed=${seed}`),blob=await r.blob();downloadBlob(blob,`tracepoint-${id}-seed-${seed}.zip`)}
